# Optional & Readonly Properties 🔒

Combine `?` for optional fields and `readonly` for immutable fields:

```typescript
interface Device {
  readonly serialNumber: string; // Cannot be altered once set
  model: string;
  warrantyYears?: number;        // Optional
}

const phone: Device = {
  serialNumber: "SN-9821-X",
  model: "iPhone 15 Pro"
};

phone.model = "iPhone 16 Pro"; // Allowed
// phone.serialNumber = "NEW-SN"; // Compile Error: Cannot assign to 'serialNumber'

console.log(phone);
```

<!-- FULL_CODE_START
interface Device {
  readonly serialNumber: string;
  model: string;
  warrantyYears?: number;
}

const phone: Device = {
  serialNumber: "SN-9821-X",
  model: "iPhone 15 Pro"
};

phone.model = "iPhone 16 Pro";
console.log("Device model:", phone.model);
console.log("Readonly serial:", phone.serialNumber);
