# Real-World: E-Commerce Catalog Model 🛒

```typescript
interface BaseEntity {
  readonly id: string;
  createdAt: Date;
}

interface Product extends BaseEntity {
  name: string;
  price: number;
  category: "electronics" | "apparel" | "books";
  tags?: string[];
}

interface CartItem {
  product: Product;
  quantity: number;
}

const cart: CartItem[] = [
  {
    product: {
      id: "P101",
      createdAt: new Date(),
      name: "USB-C Hub",
      price: 39.99,
      category: "electronics"
    },
    quantity: 2
  }
];

const subtotal = cart.reduce((sum, item) => sum + item.product.price * item.quantity, 0);
console.log("Cart Subtotal: $" + subtotal.toFixed(2));
```

